sqlGroup.select:
select a.id, a.name AS name, date_format( a.maintenance_date, '%Y-%m-%d' ) as maintenanceDate, a.maintenance_eq AS maintenanceEq, date_format( a.created_time, '%Y-%m-%d %H:%i:%s' ) as createdTime, cs.`name` AS createdStaffName
from jml_peripheral_device_mnt a left join jml_staff cs ON a.created_staff_id = cs.id
and a.created_staff_id = #{staff.staffId}
and a.prod_line_or_dept = #{staff.prodLineOrDept}
and (a.name like '%${multiFiled}%')
and a.created_time >= str_to_date(#{startDate},'%Y-%m-%d')
and a.created_time <= date_add(str_to_date(#{endDate},'%Y-%m-%d'),interval 1 day)
and a.created_staff_id = #{createdStaffId}
order by a.update_time desc
